"""Reference generated by the production C night renderer; no optical claim."""

import argparse
import os
import subprocess
import sys
import tempfile
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from simulate_ui import png, png_pixels

ROOT = Path(__file__).resolve().parents[2]


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    parser.add_argument("--update", action="store_true")
    args = parser.parse_args()
    target = ROOT / "docs/m36-night.png"
    executable = Path(os.environ.get("IB_M36_NATIVE", ROOT / "results/m36-native/policy"))
    with tempfile.TemporaryDirectory() as temporary:
        pbm = Path(temporary) / "night.pbm"
        subprocess.run(
            [
                str(executable),
                str(ROOT / "results/m36-native/bundle.json"),
                str(ROOT / "tests/fixtures/m35-wire/healthy.json"),
                str(pbm),
            ],
            check=True,
        )
        generated = png(pbm.read_bytes())
    if args.update:
        target.write_bytes(generated)
    if args.check:
        assert png_pixels(target.read_bytes()) == png_pixels(generated)
    print("PASS: synthetic production C night reference 200x200")


if __name__ == "__main__":
    main()
